  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.4,
        "text": "做跨境電商的主機了"
      },
      {
        "start": 1.4,
        "end": 3.44,
        "text": "老外充起來的亞馬遜抱在上面圖"
      },
      {
        "start": 3.44,
        "end": 4.64,
        "text": "居然不用熬夜座"
      },
      {
        "start": 4.64,
        "end": 6.16,
        "text": "能靠永遠迎接上城"
      },
      {
        "start": 6.16,
        "end": 7.84,
        "text": "今天用一分鐘教會你用"
      },
      {
        "start": 7.84,
        "end": 9.68,
        "text": "AI做出爆喊這個來電上圖"
      },
      {
        "start": 9.68,
        "end": 11.24,
        "text": "新手小白也能秒上手"
      },
      {
        "start": 11.24,
        "end": 12.16,
        "text": "方法超簡單"
      },
      {
        "start": 12.16,
        "end": 13.48,
        "text": "隨手拍一張採面圖"
      },
      {
        "start": 13.48,
        "end": 14.76,
        "text": "導入美圖設計室"
      },
      {
        "start": 14.76,
        "end": 16.68,
        "text": "宣託平台 輿重 圖片尺寸"
      },
      {
        "start": 16.68,
        "end": 18.4,
        "text": "賣點文在AI就能幫你寫"
      },
      {
        "start": 18.4,
        "end": 19.72,
        "text": "簡單改改就能用"
      },
      {
        "start": 19.72,
        "end": 21.28,
        "text": "再選擇想要的主離風格"
      },
      {
        "start": 21.28,
        "end": 22.72,
        "text": "一件就能生區當圖"
      },
      {
        "start": 22.72,
        "end": 23.88,
        "text": "你看在初圖效果"
      },
      {
        "start": 23.88,
        "end": 26.08,
        "text": "不僅完全貼了跨境平台的圖片規範"
      },
      {
        "start": 26.08,
        "end": 27.04,
        "text": "還是精準抽中"
      },
      {
        "start": 27.04,
        "end": 30.8,
        "text": "採面的核心賣點"
      },
      {
        "start": 30.8,
        "end": 32.6,
        "text": "主圖搞定了直接點A加詳情頁"
      },
      {
        "start": 32.6,
        "end": 34.16,
        "text": "配到詳情圖一件搞定"
      },
      {
        "start": 34.16,
        "end": 35.8,
        "text": "還是同一張隨手拍的圖"
      },
      {
        "start": 35.8,
        "end": 37.16,
        "text": "原用主圖賣點配置"
      },
      {
        "start": 37.16,
        "end": 38.56,
        "text": "選擇要暫時的模塊"
      },
      {
        "start": 38.56,
        "end": 40.36,
        "text": "AI會先給你每張圖的文案"
      },
      {
        "start": 40.36,
        "end": 41.56,
        "text": "上升前隨便改"
      },
      {
        "start": 41.56,
        "end": 42.84,
        "text": "省時間又省成本"
      },
      {
        "start": 42.84,
        "end": 44.2,
        "text": "碰到這上值的詳情頁"
      },
      {
        "start": 44.2,
        "end": 45.48,
        "text": "專業圖直接拉馬"
      },
      {
        "start": 45.48,
        "end": 47.52,
        "text": "哪怕只給了一張出操了失敗圖"
      },
      {
        "start": 47.52,
        "end": 48.72,
        "text": "AI也能精準歡迎"
      },
      {
        "start": 48.72,
        "end": 50,
        "text": "產品的每一柱細節"
      },
      {
        "start": 50,
        "end": 51.48,
        "text": "整套圖風格高度統一"
      },
      {
        "start": 51.48,
        "end": 53.36,
        "text": "完全不怕主圖的詳情拖解"
      },
      {
        "start": 53.36,
        "end": 54.16,
        "text": "有了這神器"
      },
      {
        "start": 54.16,
        "end": 55.44,
        "text": "新手也能進入搞定"
      },
      {
        "start": 55.44,
        "end": 58.68,
        "text": "跨境電腦的全套視覺還要做不出告款鏈接嗎?"
      }
    ],
